 45	export const SPEAKING_HOLD_MS = 700;
 46	/** Words still unclaimed after the user has been quiet this long were a request GPT-Live said yes to but never handed off. */
 47	export const UNCLAIMED_MS = 4000;
 48	const SMALL_TALK = /\b(hi|hey|hello|yo|thanks|thank you|bye|good (morning|evening|night)|how are you( doing)?( today)?|i'?m (good|fine|okay)|okay|ok|yeah|yes|no|um+|uh+|mm+|mm-?hm|(can|could|would|will) you( also)?( please)?( tell me| say)?)\b/gi;
 49	const ASKS = /\?|\b(how much|what|when|where|who|which|why|check|show|tell|add|spent|spend|paid|pay|lent|lend|borrowed?|owe|bought|received|transfer|budget|save|balance|cancel|remove|change)\b/i;
 50	/** Whether unclaimed words ask for something, rather than being small talk GPT-Live answered itself. */
 51	export function looksLikeRequest(text: string) {
 52	  const rest = text.replace(SMALL_TALK, " ").trim();
 53	  return rest.split(/\s+/).filter(Boolean).length >= 3 && ASKS.test(rest);
 54	}
 55	export const SLOW_TASK_MS = 8000;
 56	/** Moneo silent this long after it began saying a result means it said all of it. The user's words are transcribed
 57	 * about a second late, so words arriving sooner than this were said over the result. */
 58	export const RESULT_DONE_MS = 2500;
 59	/** Longest wait for Moneo to start saying a result before the next is handed over anyway. */
 60	export const RESULT_TURN_MS = 20_000;
 61	/** A pause this long ends the user's turn for handing over a result; people pause mid-sentence ("uh… like…"). */
 62	export const USER_PAUSE_MS = 1500;
 63	/** How long Moneo gets to answer an interruption before it is asked to finish the result it was cut off in. */
 64	export const RESUME_AFTER_MS = 3000;
