 70	export class VoiceCallController {
 71	  captions: CallCaption[] = [];
 72	  tasks: CallTask[] = [];
 73	  error = "";
 74	  /** Words the user said that no hand-off has claimed yet, with when each piece ended in the session. */
 75	  private heard: { text: string; end: number }[] = [];
 76	  private lastUserTurn = "";
 77	  private lastDelegation: string | null = null;
 78	  /** A request started from unclaimed words, which a late hand-off of the same words takes over instead of repeating. */
 79	  private unclaimedTask: string | null = null;
 80	  private answers = new Map<string, string>();
 81	  private lastUserSpeech = -Infinity;
 82	  private lastAssistantSpeech = -Infinity;
 83	  /** When Moneo was last audible in the call's audio. Transcript text runs ahead of the voice, so once the audio is
 84	   * metered it, not the transcript, says whether Moneo is talking. */
 85	  private lastAudible = -Infinity;
 86	  private metered = false;
 87	  private outbox: { delegationId: string | null; content: string }[] = [];
 88	  private flushing = false;
 89	  /** The result Moneo was last handed and when, until it has said all of it or was talked over. */
 90	  private current: { delegationId: string | null; content: string; at: number } | null = null;
 91	  /** A result the user talked over, with what they said since, until Moneo is asked to finish it. */
 92	  private cut: { delegationId: string | null; content: string; words: string } | null = null;
 93	  private captionId = 0;
 94	  /** A sound tag ("[scoff]") still open at the end of a role's last words, held until it closes. */
 95	  private openTag: Record<CallCaption["role"], string> = { user: "", assistant: "" };
 96	  private readonly now: () => number;
 97	  private readonly schedule: (run: () => void, ms: number) => unknown;
 98	  private readonly newId: () => string;
