100	  constructor(private readonly deps: Deps) {
101	    this.now = deps.now ?? (() => Date.now());
102	    this.schedule = deps.schedule ?? ((run, ms) => setTimeout(run, ms));
103	    this.newId = deps.newId ?? (() => crypto.randomUUID());
104	  }
