106	  get running() { return this.tasks.filter(task => task.status === "running"); }
107	  get cards() { return this.tasks.flatMap(task => task.cards); }
108	  /** When Moneo last made a sound: its metered voice once there is one, else its transcript. */
109	  private get lastMoneo() { return this.metered ? this.lastAudible : this.lastAssistantSpeech; }
110	  /** Someone is talking right now. */
111	  speaking(by: "user" | "any" = "any") {
112	    const last = by === "user" ? this.lastUserSpeech : Math.max(this.lastUserSpeech, this.lastMoneo);
113	    return this.now() - last < SPEAKING_HOLD_MS;
114	  }
115	  /** Called while Moneo's voice is audible in the call. */
116	  heardMoneo() { this.metered = true; this.lastAudible = this.now(); }
