118	  /** Whether Moneo has said the result it was handed: it began, then went quiet with nobody talking over it. */
119	  private resultSaid() {
120	    const current = this.current;
121	    if (!current) return true;
122	    const began = this.lastMoneo > current.at;
123	    return began ? this.now() - this.lastMoneo >= RESULT_DONE_MS : this.now() - current.at > RESULT_TURN_MS;
124	  }
