126	  handle(event: ServerEvent) {
127	    switch (event.type) {
128	      case "session.input_transcript.delta":
129	        // Talking over a result GPT-Live is saying stops it, and the rest would be lost.
130	        if (this.current && this.lastMoneo > this.current.at && !this.resultSaid()) {
131	          this.cut = { delegationId: this.current.delegationId, content: this.current.content, words: "" };
132	          this.deps.log?.(`cut off: ${this.current.content.slice(0, 60)}`);
133	          this.current = null;
134	          this.resume();
135	        }
136	        if (this.cut) this.cut.words += event.delta ?? "";
137	        this.lastUserSpeech = this.now();
138	        this.heard.push({ text: event.delta ?? "", end: event.end_ms ?? Infinity });
139	        this.caption("user", event.delta ?? "");
140	        this.schedule(() => this.claimUnheard(), UNCLAIMED_MS);
141	        break;
142	      case "session.output_transcript.delta":
143	        this.lastAssistantSpeech = this.now();
144	        this.caption("assistant", event.delta ?? "");
145	        break;
146	      case "session.delegation.created": {
147	        // The delegation carries no task text: it is what the user said up to its offset since the previous one;
148	        // words said after the offset belong to the next request.
149	        const offset = event.offset_ms ?? Infinity;
150	        const claimed = this.heard.some(piece => piece.end <= offset) ? this.heard.filter(piece => piece.end <= offset) : this.heard;
151	        this.heard = this.heard.filter(piece => !claimed.includes(piece));
152	        const words = claimed.map(piece => piece.text).join("").replace(/\[[^\]]*\]/g, "").trim();
153	        if (event.delegation?.id) this.lastDelegation = event.delegation.id;
154	        // A late hand-off for words already started as their own request answers through that one.
155	        if (event.delegation?.id && !words && this.unclaimedTask) { this.update(this.unclaimedTask, { delegationId: event.delegation.id }); this.unclaimedTask = null; break; }
156	        this.unclaimedTask = null;
157	        const text = words || this.lastUserTurn;
158	        if (event.delegation?.id && text) this.start(text, event.delegation.id);
159	        break;
160	      }
161	      case "error":
162	        this.error = event.error?.message ?? event.message ?? "The call had a problem";
163	        this.deps.onChange();
164	        break;
165	    }
166	  }
