182	  /** A typed message starts a task directly; its answer is spoken the same way. */
183	  typed(text: string) {
184	    const message = text.trim();
185	    if (!message) return;
186	    this.captionId++;
187	    this.captions = [...this.captions, { id: this.captionId, role: "user", text: message }];
188	    this.start(message, null);
189	  }
