191	  private caption(role: CallCaption["role"], words: string) {
192	    // Sound tags are not words, and can arrive in pieces between the other side's words.
193	    let delta = (this.openTag[role] + words).replace(/\[[^\]]*\]/g, "");
194	    // A "[" that never closes within a few words was just a bracket.
195	    const open = delta.length - delta.lastIndexOf("[") > 40 ? -1 : delta.lastIndexOf("[");
196	    this.openTag[role] = open < 0 ? "" : delta.slice(open);
197	    if (open >= 0) delta = delta.slice(0, open);
198	    if (!delta) return;
199	    const last = this.captions.at(-1);
200	    if (last?.role === role) this.captions = [...this.captions.slice(0, -1), { ...last, text: last.text + delta }];
201	    else this.captions = [...this.captions, { id: ++this.captionId, role, text: delta.trimStart() }];
202	    if (role === "user") this.lastUserTurn = this.captions.at(-1)!.text.trim();
203	    this.deps.onChange();
204	  }
