206	  private update(requestId: string, change: Partial<CallTask>) {
207	    this.tasks = this.tasks.map(task => task.requestId === requestId ? { ...task, ...change } : task);
208	    this.deps.onChange();
209	  }
210	
211	  /**
212	   * What Moneo needs to answer one request on its own: the requests still being answered separately, the call so far
213	   * to resolve "that" or "also", and what this call has already answered.
214	   */
215	  private brief() {
216	    return {
217	      via: "call", input: "voice",
218	      runningTasks: this.running.slice(-5).map(task => ({ requestId: task.requestId, text: task.text.slice(0, 300) })),
219	      recentTurns: this.captions.slice(-6).map(caption => ({ role: caption.role, text: caption.text.slice(-300) })),
220	      answered: this.tasks.filter(task => this.answers.has(task.requestId)).slice(-4).map(task => ({ text: task.text.slice(0, 150), answer: this.answers.get(task.requestId)!.slice(0, 300) })),
221	    };
222	  }
