224	  private start(text: string, delegationId: string | null) {
225	    const requestId = this.newId();
226	    const context = this.brief();
227	    this.tasks = [...this.tasks, { requestId, text, step: "starting", status: "running", delegationId, cards: [] }];
228	    this.deps.onChange();
229	    this.watchSlow(requestId);
230	    void this.run(requestId, text, context);
231	    return requestId;
232	  }
