234	  private async run(requestId: string, text: string, context: ReturnType<VoiceCallController["brief"]>) {
235	    const label = `"${text.slice(0, 120)}"`;
236	    // Read when needed: a late hand-off can take a request over while it runs.
237	    const via = () => this.tasks.find(item => item.requestId === requestId)?.delegationId ?? null;
238	    try {
239	      const result = await this.deps.ask({ conversationId: this.deps.conversationId, requestId, message: text.slice(0, 4000), context }, event => {
240	        if (event.type !== "tool" || event.state !== "running") return;
241	        const step = stepFor(event.name);
242	        this.update(requestId, { step });
243	        if (via()) this.deps.send({ type: "session.thinking.append", delegation_id: via(), content: `Working on ${label}: ${step}.` });
244	      });
245	      const task = this.tasks.find(item => item.requestId === requestId);
246	      // Canceled from the list, or stopped because a correction replaced it: nothing to say.
247	      if (task?.status === "canceled" || result.status === 409) { this.update(requestId, { status: "canceled", step: "stopped" }); return; }
248	      if (!result.ok || !result.body.answer) throw new Error(result.body.error ?? "No answer");
249	      const cards = answerCards(result.body.answer);
250	      this.answers.set(requestId, spokenAnswer(result.body.answer));
251	      this.update(requestId, { status: "done", step: "answered", cards });
252	      this.deps.onAnswer?.(text, result.body as ChatAnswer);
253	      // A typed request has no hand-off to answer through, so the result says outright that it is to be spoken.
254	      const delegationId = via();
255	      this.deliver(delegationId, [`Result for ${label}${delegationId ? "" : " (typed by the user in the call; say the result to them now, in the language they typed)"}: ${spokenAnswer(result.body.answer)}`,
256	        cards.length ? `${cards.length} card${cards.length > 1 ? "s" : ""} on screen to tap; nothing is saved until then.` : ""].filter(Boolean).join(" "));
257	    } catch {
258	      if (this.tasks.find(item => item.requestId === requestId)?.status === "canceled") return;
259	      this.update(requestId, { status: "failed", step: "failed" });
260	      this.deliver(via(), `Moneo couldn't get an answer for ${label}. Tell the user briefly and ask if they want you to try again.`);
261	    }
262	  }
