281	  /**
282	   * Hands over the next result once Moneo has said the previous one and nobody is talking. What is still running is
283	   * read when it goes out, so a result never says another is pending after that one has finished.
284	   */
285	  private flush() {
286	    if (this.flushing || !this.outbox.length || this.cut) return;
287	    if (this.speaking() || this.now() - this.lastUserSpeech < USER_PAUSE_MS || !this.resultSaid()) {
288	      this.flushing = true;
289	      this.schedule(() => { this.flushing = false; this.flush(); }, 300);
290	      return;
291	    }
292	    const { delegationId, content } = this.outbox.shift()!;
293	    const others = this.running.map(item => `"${item.text.slice(0, 80)}"`);
294	    this.current = { delegationId, content, at: this.now() };
295	    this.deps.log?.(`handed over: ${content.slice(0, 60)}`);
296	    this.deps.send({ type: "session.commentary.append", delegation_id: delegationId, content: others.length ? `${content} Still working on ${others.join(", ")}.` : content });
297	    this.flush();
298	  }
