364	/**
365	 * A live GPT-Live call over WebRTC. GPT-Live only talks; every question it hands off runs through /api/chat
366	 * in this conversation (see VoiceCallController), and the answer is sent back for it to speak.
367	 */
368	export function useVoiceCall(conversationId: string, onAnswer?: (question: string, answer: ChatAnswer) => void, onEnded?: () => void) {
369	  const [status, setStatus] = useState<CallStatus>("connecting");
370	  const [error, setError] = useState("");
371	  const [muted, setMuted] = useState(false);
372	  const [, render] = useReducer((count: number) => count + 1, 0);
373	  const [live] = useState(() => new Connection(onAnswer, onEnded));
374	  useEffect(() => { live.set({ onAnswer, onEnded }); });
375	
376	  const [controller] = useState(() => {
377	    const ask: CallAsk = async (payload, onEvent) => {
378	      const abort = new AbortController();
379	      live.aborts.set(payload.requestId, abort);
380	      try {
381	        const response = await fetch("/api/chat", { method: "POST", signal: abort.signal, headers: { "Content-Type": "application/json", Accept: "application/x-ndjson, application/json" }, body: JSON.stringify(payload) });
382	        return await readResponse(response, onEvent);
383	      } finally { live.aborts.delete(payload.requestId); }
384	    };
385	    return new VoiceCallController({ conversationId, ask, onChange: render, onAnswer: (question, answer) => live.onAnswer?.(question, answer),
386	      log: trace,
387	      send: event => {
388	        trace?.(`sent ${event.type}: ${String(event.content ?? "").slice(0, 100)}`);
389	        if (live.channel?.readyState === "open") live.channel.send(JSON.stringify(event));
390	      } });
391	  });
