   146	/** Starts a GPT-Live WebRTC session for the browser's offer; the API key stays on the server. */
   147	export async function POST(request: Request) {
   148	  let context: Awaited<ReturnType<typeof requireWorkspace>>;
   149	  try { context = await requireWorkspace(); } catch { return Response.json({ error: "Unauthorized" }, { status: 401 }); }
   150	  const parsed = inputSchema.safeParse(await request.json().catch(() => null));
   151	  if (!parsed.success) return Response.json({ error: "Invalid call request" }, { status: 400 });
   152	  if (!process.env.OPENAI_API_KEY) return Response.json({ error: "Voice isn't set up on this server: OPENAI_API_KEY is missing" }, { status: 503 });
   153	  const { sdp, conversationId } = parsed.data;
   154	  const { supabase, workspace, settings } = context;
   155	  const existing = await supabase.from("conversations").select("id, deleted_at").eq("workspace_id", workspace.id).eq("id", conversationId).maybeSingle();
   156	  if (existing.error) throw existing.error;
   157	  if (existing.data?.deleted_at) return Response.json({ error: "Conversation was deleted" }, { status: 404 });
   158	  // A new chat has no row yet; its first call request creates it.
   159	  let history: { role: string; content: string }[] = [];
   160	  if (existing.data) {
   161	    const { data, error } = await supabase.from("messages").select("role, content").eq("workspace_id", workspace.id).eq("conversation_id", conversationId)
   162	      .order("created_at", { ascending: false }).limit(10);
   163	    if (error) throw error;
   164	    history = (data ?? []).reverse();
   165	  }
   166	  try {
   167	    const session = await openai.experimental_realtime(VOICE_MODEL).doCreateWebRTCSession({ sdp, abortSignal: request.signal, sessionConfig: {
   168	      instructions: VOICE_INSTRUCTIONS, voice: settings.voice,
   169	      providerOptions: { openai: { delegation: { type: "client" }, input: seedInput(history) } },
   170	    } });
   171	    return Response.json({ sdp: session.sdp, sessionId: session.sessionId });
   172	  } catch (error) {
   173	    console.error("voice session failed", error);
   174	    return Response.json({ error: "Could not start the call" }, { status: 502 });
   175	  }
